import asyncio
import os
from claude_agent_sdk import (
    ClaudeSDKClient, ClaudeAgentOptions, HookMatcher,
    AssistantMessage, ResultMessage,
)
from dotenv import load_dotenv

load_dotenv(override=True)


async def protect_modify_env_files(input_data, tool_use_id, context):
    file_path = input_data["tool_input"].get("file_path", "")
    file_name = file_path.split("/")[-1]

    if file_name == ".env":
        return {
            # Top-level field: message shown to the user
            "systemMessage": "Remember: .env file is protected.",
            "hookSpecificOutput": {
                "hookEventName": input_data["hook_event_name"],
                "permissionDecision": "deny",
                "permissionDecisionReason": "Cannot modify .env files",
            }
        }
    return {}  # 返回空 dict = 放行


async def protect_read_env_files(input_data, tool_use_id, context):
    if input_data["hook_event_name"] != "PreToolUse":
        return {}
    file_path = input_data["tool_input"].get("file_path", "")
    file_name = file_path.split("/")[-1]
    if file_name == ".env":
        return {
            "hookSpecificOutput": {
                "hookEventName": input_data["hook_event_name"],
                "permissionDecision": "deny",
                "permissionDecisionReason": "Cannot read .env files",
            }
        }
    return {}  # 返回空 dict = 放行

async def auto_approve_read_only(input_data, tool_use_id, context):
    print(f"[HOOK] auto_approve_read_only called, tool_name={input_data.get('tool_name')}")

    if input_data["hook_event_name"] != "PreToolUse":
        print("[HOOK] -> skip, not PreToolUse")
        return {}

    read_only_tools = ["Read", "Glob", "Grep"]
    if input_data["tool_name"] in read_only_tools:
        print(f"[HOOK] -> auto-approved: {input_data['tool_name']}")
        return {
            "hookSpecificOutput": {
                "hookEventName": input_data["hook_event_name"],
                "permissionDecision": "allow",
                "permissionDecisionReason": "Read-only tool auto-approved",
            }
        }

    print(f"[HOOK] -> pass through (no decision), tool_name={input_data['tool_name']}")
    return {}

async def main():
    options = ClaudeAgentOptions(
        env={
            "ANTHROPIC_BASE_URL": "https://api.moonshot.cn/anthropic",
            "ANTHROPIC_MODEL": "kimi-k2.5",
            "ANTHROPIC_SMALL_FAST_MODEL": "kimi-k2.5",
            "ANTHROPIC_API_KEY": os.getenv("ANTHROPIC_API_KEY"),
        },
        setting_sources=[],
        hooks={
            "PreToolUse": [
                HookMatcher(matcher="Write|Edit", hooks=[protect_modify_env_files]),
                # HookMatcher(matcher="Read", hooks=[protect_read_env_files]),
                HookMatcher(matcher="Read", hooks=[auto_approve_read_only])
                ]
        }
    )
    async with ClaudeSDKClient(options=options) as client:
        # await client.query("创建一个 .env 文件，写入本地开发数据库配置")
        await client.query("读取 `./agent_scaffold/10_claudecode_hooks/readable_data.txt` 文件，并打印到日志中")
        async for message in client.receive_response():
            if isinstance(message, (AssistantMessage, ResultMessage)):
                print(message)

asyncio.run(main())

